mapper.select:
WITH me AS ( SELECT gender, bmi, trait_companion, trait_competition, trait_place, trait_intensity, TIMESTAMPDIFF(YEAR, birth_date, CURDATE()) AS age FROM users WHERE user_id = #{userId} ), myage AS ( SELECT me.*, CASE WHEN age >= 70 THEN '70대이상' ELSE CONCAT(FLOOR(age / 10) * 10, '대') END AS age_group FROM me ) SELECT s.sport_id, s.name, s.category, s.is_indoor, s.min_people, s.is_competitive, s.met_value, s.description,
/* 성향 : 4개 축 점수의 평균 */ (SELECT AVG(t.score) FROM sport_traits t WHERE t.sport_id = s.sport_id AND ( (t.axis = 'COMPANION' AND t.option_code = m.trait_companion) OR (t.axis = 'COMPETITION' AND t.option_code = m.trait_competition) OR (t.axis = 'PLACE' AND t.option_code = m.trait_place) OR (t.axis = 'INTENSITY' AND t.option_code = m.trait_intensity) ) ) AS trait_score,
/* 통계 : 연령대+성별 -> 연령대 -> 전체 순으로 대체 */ COALESCE( (SELECT r.participation_rate FROM sport_retention_stats r WHERE r.sport_id = s.sport_id AND r.gender = m.gender AND r.age_group = m.age_group), (SELECT r.participation_rate FROM sport_retention_stats r WHERE r.sport_id = s.sport_id AND r.gender IS NULL AND r.age_group = m.age_group), (SELECT r.participation_rate FROM sport_retention_stats r WHERE r.sport_id = s.sport_id AND r.gender IS NULL AND r.age_group IS NULL) ) AS participation_rate,
/* 접근성 : 시설종목은 최근접 시설, 야외종목은 최근접 코스 시작점 */ CASE s.category WHEN 'FACILITY' THEN ( SELECT MIN(6371 * ACOS(LEAST(1, COS(RADIANS(#{lat})) * COS(RADIANS(f.lat)) * COS(RADIANS(f.lng) - RADIANS(#{lng})) + SIN(RADIANS(#{lat})) * SIN(RADIANS(f.lat))))) FROM facility_sports fs JOIN facilities f ON f.facility_id = fs.facility_id WHERE fs.sport_id = s.sport_id AND f.is_active = 1) ELSE ( SELECT MIN(6371 * ACOS(LEAST(1, COS(RADIANS(#{lat})) * COS(RADIANS(c.start_lat)) * COS(RADIANS(c.start_lng) - RADIANS(#{lng})) + SIN(RADIANS(#{lat})) * SIN(RADIANS(c.start_lat))))) FROM courses c WHERE c.is_active = 1 AND c.course_type = CASE s.name WHEN '등산' THEN 'HIKE' ELSE 'WALK' END) END AS nearest_km
FROM sports s CROSS JOIN myage m WHERE s.is_active = 1 AND s.category <> 'HOME' ORDER BY s.sport_id
